  pointTitle: string;
  persuasiveTechnique: string;
  argument: string;
  evidence: string;
  impact: string;
}

const ROLES = {
  proposition: [
    { id: 'prop1', label: '1st Proposition', desc: 'Defines motion, sets case.' },
    { id: 'prop2', label: '2nd Proposition', desc: 'Defends case, rebuts Opp 1.' },
    { id: 'prop3', label: '3rd Proposition', desc: 'Summarizes clashes, rebuts.' },
    { id: 'propReply', label: 'Prop Reply', desc: 'Summarizes case, explains victory.' },
  ],
  opposition: [
    { id: 'opp1', label: '1st Opposition', desc: 'Challenges definition, rebuts Prop 1.' },
    { id: 'opp2', label: '2nd Opposition', desc: 'Rebuts Prop 2, new arguments.' },
    { id: 'opp3', label: '3rd Opposition', desc: 'Summarizes clashes, rebuts.' },
    { id: 'oppReply', label: 'Opp Reply', desc: 'Summarizes case, explains victory.' },
  ]
};

const DebateHelper: React.FC = () => {
  const [debateTopic, setDebateTopic] = useState<string>('');
  const [selectedRole, setSelectedRole] = useState<string | null>(null);
  const [generatedPoints, setGeneratedPoints] = useState<DebatePoint[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);

  const handleTopicChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setDebateTopic(event.target.value);
  };

  const handleRoleSelect = (roleId: string) => {
    setSelectedRole(roleId);
    setGeneratedPoints([]);
    setError(null);
  };

  const handleClearAll = () => {
    setDebateTopic('');
    setSelectedRole(null);
    setGeneratedPoints([]);
    setIsLoading(false);
    setError(null);
  };

  const generateSpeech = async () => {
    if (!debateTopic.trim() || !selectedRole) {
      setError('Please enter a topic and select a speaker role.');
      return;
    }

    setIsLoading(true);
    setError(null);
    setGeneratedPoints([]);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-2.5-flash';

    // Determine full role name for the prompt
    const allRoles = [...ROLES.proposition, ...ROLES.opposition];
    const roleObj = allRoles.find(r => r.id === selectedRole);
    const roleName = roleObj ? roleObj.label : selectedRole;

    const prompt = `
      Act as a world-class debate coach for the World Schools Debating Championship (WSDC).

      Motion: "${debateTopic}"
      Speaker Role: ${roleName}

      Generate 3 distinct, high-quality speech points appropriate for this specific speaker role.

      For each point, strictly follow this structure:
      1. Point Title: A short, catchy header for the argument.
      2. Persuasive Hook: A specific rhetorical device (Anaphora, Triplet, or Rhetorical Question) to introduce the point.
      3. Argument: The core logical reasoning (ARE structure - Assertion, Reasoning).
      4. Evidence: A real-world example, statistic, or specific citation.
      5. Impact: Why this argument wins the debate (Significance/Impact).

      Return the response as a JSON array.
    `;

    const responseSchema: Schema = {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          pointTitle: { type: Type.STRING },
          persuasiveTechnique: { type: Type.STRING, description: "The rhetorical device text (e.g., 'Anaphora: We cannot wait, we cannot...')" },
          argument: { type: Type.STRING, description: "The logical reasoning" },
          evidence: { type: Type.STRING, description: "Real world example or source" },
          impact: { type: Type.STRING, description: "Why this matters/impact" },
        },
        required: ['pointTitle', 'persuasiveTechnique', 'argument', 'evidence', 'impact'],
      },
    };

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: prompt,
        config: {
          responseMimeType: 'application/json',
          responseSchema: responseSchema,
        },
      });

      const jsonStr = response.text?.trim();
      if (jsonStr) {
        const parsedPoints: DebatePoint[] = JSON.parse(jsonStr);
        setGeneratedPoints(parsedPoints);
      } else {
        setError('No response received from the AI.');
      }
