      console.error('Error generating speech:', error);
      setError(`Failed to generate speech: ${error.message || 'Unknown error'}`);
    } finally {
      setIsLoading(false);
    }
  };

  const isProp = selectedRole && ROLES.proposition.some(r => r.id === selectedRole);

  return (
    <div className="app-container">
      <header>
        <h1>DebateCoach AI</h1>
        <p className="subtitle">World Schools Style Preparation Tool</p>
      </header>

      <main>
        <section className="setup-section">
          <div className="input-group">
            <label htmlFor="debate-topic">Motion / Topic</label>
            <textarea
              id="debate-topic"
              value={debateTopic}
              onChange={handleTopicChange}
              placeholder="e.g., This House Believes That social media does more harm than good."
              rows={3}
            />
          </div>

          <div className="role-selection">
            <h3 className="section-title">Select Speaker Role</h3>
            <div className="teams-container">
              <div className="team-column proposition">
                <h4>Proposition (Gov)</h4>
                <div className="role-grid">
                  {ROLES.proposition.map((role) => (
                    <button
                      key={role.id}
                      className={`role-card ${selectedRole === role.id ? 'selected' : ''}`}
                      onClick={() => handleRoleSelect(role.id)}
                      title={role.desc}
                    >
                      <span className="role-label">{role.label}</span>
                      <span className="role-desc">{role.desc}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="team-column opposition">
                <h4>Opposition (Opp)</h4>
                <div className="role-grid">
                  {ROLES.opposition.map((role) => (
                    <button
                      key={role.id}
                      className={`role-card ${selectedRole === role.id ? 'selected' : ''}`}
                      onClick={() => handleRoleSelect(role.id)}
                      title={role.desc}
                    >
                      <span className="role-label">{role.label}</span>
                      <span className="role-desc">{role.desc}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="action-bar">
             <button
              onClick={generateSpeech}
              disabled={isLoading || !debateTopic.trim() || !selectedRole}
              className={`generate-button ${isProp ? 'theme-prop' : 'theme-opp'} ${!selectedRole ? 'theme-neutral' : ''}`}
