const DebateWorkspace: React.FC<{ user: UserProfile, onUpdatePlan: (plan: PlanType) => void }> = ({ user, onUpdatePlan }) => {
  const [debateTopic, setDebateTopic] = useState<string>('');
  const [selectedRole, setSelectedRole] = useState<string | null>(null);
  const [generatedPoints, setGeneratedPoints] = useState<DebatePoint[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);

  const handleTopicChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
    setDebateTopic(event.target.value);
  };

  const handleRoleSelect = (roleId: string) => {
    // Check for free plan restrictions
    if (user.plan === 'free') {
       const isAdvancedRole = ['prop2', 'prop3', 'propReply', 'opp2', 'opp3', 'oppReply'].includes(roleId);
       if (isAdvancedRole) {
         setShowUpgradeModal(true);
         return;
       }
    }
    setSelectedRole(roleId);
    setGeneratedPoints([]);
    setError(null);
  };

  const handleClearAll = () => {
    setDebateTopic('');
    setSelectedRole(null);
    setGeneratedPoints([]);
    setIsLoading(false);
    setError(null);
  };

  const generateSpeech = async () => {
    if (!debateTopic.trim() || !selectedRole) {
      setError('Please enter a topic and select a speaker role.');
      return;
    }

    // Check usage limits for free plan
    if (user.plan === 'free' && user.creditsUsed >= user.creditsLimit) {
      setShowUpgradeModal(true);
      return;
    }

    setIsLoading(true);
    setError(null);
    setGeneratedPoints([]);

    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const model = 'gemini-2.5-flash';

    const allRoles = [...ROLES.proposition, ...ROLES.opposition];
    const roleObj = allRoles.find(r => r.id === selectedRole);
    const roleName = roleObj ? roleObj.label : selectedRole;

    const prompt = `
      Act as a world-class debate coach for the World Schools Debating Championship (WSDC).
      Motion: "${debateTopic}"
      Speaker Role: ${roleName}
      Generate 3 distinct, high-quality speech points.
      Structure: Title, Persuasive Hook, Argument (ARE), Evidence, Impact.
      Return JSON array.
    `;

    const responseSchema: Schema = {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          pointTitle: { type: Type.STRING },
          persuasiveTechnique: { type: Type.STRING },
          argument: { type: Type.STRING },
          evidence: { type: Type.STRING },
          impact: { type: Type.STRING },
        },
        required: ['pointTitle', 'persuasiveTechnique', 'argument', 'evidence', 'impact'],
      },
    };

    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: prompt,
        config: { responseMimeType: 'application/json', responseSchema: responseSchema },
      });

      const jsonStr = response.text?.trim();
      if (jsonStr) {
        setGeneratedPoints(JSON.parse(jsonStr));
      } else {
        setError('No response received from the AI.');
      }
    } catch (error: any) {
      setError(`Failed to generate: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const isProp = selectedRole && ROLES.proposition.some(r => r.id === selectedRole);

  return (
    <div className="workspace-container">
      <UpgradeModal 
        isOpen={showUpgradeModal} 
        onClose={() => setShowUpgradeModal(false)} 
        onUpgrade={onUpdatePlan}
      />

      <div className="dashboard-header-bar">
        <div className="header-text">
          <h1>Case Workspace</h1>
          <p>Prepare your next case.</p>
        </div>
        <div className="plan-status-card">
          <div className="status-info">
             <span className="status-label">CURRENT PLAN</span>
             <span className={`status-value ${user.plan}`}>{user.plan.toUpperCase()}</span>
          </div>
          <div className="usage-info">
             {user.plan === 'free' ? `${user.creditsUsed}/${user.creditsLimit} Generations used` : 'Unlimited Access'}
          </div>
          {user.plan === 'free' && (
             <button className="upgrade-sm-btn" onClick={() => setShowUpgradeModal(true)}>Upgrade</button>
          )}
        </div>
      </div>

      <section className="setup-section">
          <div className="input-group">
            <label htmlFor="debate-topic">Motion / Topic</label>
            <textarea
              id="debate-topic"
              value={debateTopic}
              onChange={handleTopicChange}
              placeholder="e.g., THBT social media does more harm than good."
              rows={3}
            />
          </div>

          <div className="role-selection">
            <h3 className="section-title">Select Speaker Role</h3>
            <div className="teams-container">
              <div className="team-column proposition">
                <h4>Proposition (Gov)</h4>
                <div className="role-grid">
                  {ROLES.proposition.map((role) => (
                    <button
                      key={role.id}
                      className={`role-card ${selectedRole === role.id ? 'selected' : ''}`}
                      onClick={() => handleRoleSelect(role.id)}
                    >
                      <div className="role-content-row">
                        <span className="role-label">{role.label}</span>
                         {user.plan === 'free' && ['prop2', 'prop3', 'propReply'].includes(role.id) && <span className="lock-icon">🔒</span>}
                      </div>
                      <span className="role-desc">{role.desc}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="team-column opposition">
                <h4>Opposition (Opp)</h4>
                <div className="role-grid">
                  {ROLES.opposition.map((role) => (
                    <button
                      key={role.id}
                      className={`role-card ${selectedRole === role.id ? 'selected' : ''}`}
                      onClick={() => handleRoleSelect(role.id)}
                    >
                      <div className="role-content-row">
                        <span className="role-label">{role.label}</span>
                        {user.plan === 'free' && ['opp2', 'opp3', 'oppReply'].includes(role.id) && <span className="lock-icon">🔒</span>}
                      </div>
                      <span className="role-desc">{role.desc}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          <div className="action-bar">
             <button
              onClick={generateSpeech}
              disabled={isLoading || !debateTopic.trim() || !selectedRole}
              className={`generate-button ${isProp ? 'theme-prop' : 'theme-opp'} ${!selectedRole ? 'theme-neutral' : ''}`}
            >
              {isLoading ? 'Coaching...' : 'Generate Speech Points'}
            </button>
            <button onClick={handleClearAll} className="clear-button">
              Reset
            </button>
          </div>
          {error && <div className="error-banner">{error}</div>}
      </section>

      {generatedPoints.length > 0 && (
          <section className="results-section">
            <h2 className={`results-header ${isProp ? 'text-prop' : 'text-opp'}`}>
              Generated Outline
            </h2>
            <div className="cards-container">
              {generatedPoints.map((point, index) => (
                <div key={index} className={`speech-card ${isProp ? 'border-prop' : 'border-opp'}`}>
                  <div className="card-header">
                    <span className="point-number">Point {index + 1}</span>
                    <h3>{point.pointTitle}</h3>
                  </div>
                  <div className="card-body">
                    <div className="structure-block persuasive">
                      <span className="block-label">Persuasive Hook</span>
                      <p>{point.persuasiveTechnique}</p>
                    </div>
                    <div className="structure-block argument">
                      <span className="block-label">Argument & Reasoning</span>
                      <p>{point.argument}</p>
                    </div>
                    <div className="structure-block evidence">
                      <span className="block-label">Evidence / Example</span>
                      <p>{point.evidence}</p>
                    </div>
                    <div className="structure-block impact">
                      <span className="block-label">Impact</span>
                      <p>{point.impact}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>
        )}
    </div>
  );
};

