    // Simulate login with default free plan
    setUser({
      name: 'Debater',
      plan: 'free',
      creditsUsed: 1,
      creditsLimit: 3
    });
    setView('dashboard');
  };

  const handleLogout = () => {
    setUser(null);
    setView('landing');
  };

  const handleUpdatePlan = (newPlan: PlanType) => {
    if (user) {
      setUser({
        ...user,
        plan: newPlan,
        creditsLimit: newPlan === 'free' ? 3 : -1
      });
    }
  };

  return (
    <div className="app-root">
      <Navbar 
        onNavigate={setView} 
        isLoggedIn={!!user} 
        user={user}
        onLogout={handleLogout} 
      />

      <main className="main-content">
        {view === 'landing' && (
          <>
            <Hero onGetStarted={() => setView(!!user ? 'dashboard' : 'signup')} />
            <Testimonials />
            <section className="pricing-section">
                <h2>Choose Your <span className="text-highlight">Winning Edge</span></h2>
                <PricingCards onSelect={(plan) => { if(plan !== 'team') setView('signup'); }} />
            </section>
          </>
        )}

        {view === 'login' && (
          <AuthForm 
            mode="login" 
            onSubmit={handleLogin} 
            onSwitch={() => setView('signup')} 
          />
        )}

        {view === 'signup' && (
          <AuthForm 
            mode="signup" 
            onSubmit={handleLogin} 
            onSwitch={() => setView('login')} 
          />
        )}

        {view === 'dashboard' && user && (
          <DebateWorkspace user={user} onUpdatePlan={handleUpdatePlan} />
        )}
      </main>

      <footer className="footer">
        <p>&copy; 2024 DebateCoach AI. All rights reserved.</p>
      </footer>
    </div>
  );
};

